let table: Map<string, string> | null = null;

/** 命名字符引用对应的字符；不认识的名称返回 undefined */
export function lookupEntity(name: string): string | undefined {
  if (!table) {
    table = new Map();
    for (const entry of PACKED.split('\u0001')) {
      const separator = entry.indexOf('\u0002');
      table.set(entry.slice(0, separator), entry.slice(separator + 1));
    }
  }
  return table.get(name);
}
